 font-family: "Inter Tight", sans-serif !important;
}

.globo-formbuilder .header {
 box-shadow: unset!important;
}

.globo-formbuilder .title {
 margin-top: 0!important;
 font-weight: 600 !important;
 color: #000!important;
 font-family: Inter Tight, sans-serif !important;
}

.globo-formbuilder .title,
.globo-formbuilder .description,
.globo-formbuilder label {
 font-family: "Inter Tight", sans-serif !important;
}

.globo-form-app:not([data-id="96192"]) {
 width: 100% !important;
 margin: 0 !important;
 max-width: 100% !important;
 padding: 0 !important;
}

.globo-form-app:not([data-id="96192"]) .panel.block-container {
 /*padding-top: 0;*/
 display: flex;
 flex-direction: column;
 row-gap: 40px !important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-control {
 margin: 0 !important;
 padding: 0 !important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-input {
 border: 0 !important;
 border-bottom: 1.5px solid #000 !important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-input .line-input {
 height: 23px;
 min-width: auto;
 width: 100%;
 box-shadow: none;
 padding: 0;
 font-family: "Inter Tight", sans-serif !important;
 -webkit-text-fill-color: unset !important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-input select.line-input {
 -webkit-text-fill-color: rgba(0, 0, 0, 0.4) !important;
 background-image: url(https://cdn.shopify.com/s/files/1/0659/3966/9171/files/select_arrow.png?v=1742317594) !important;
 background-repeat: no-repeat !important;
 background-position: right 10px center !important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-input textarea.line-input {
 height: 50px;
 min-height: 50px!important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-input .line-input:focus {
 box-shadow: unset !important;
}

.globo-form-app:not([data-id="96192"]) .globo-form-input .line-input::placeholder {
 color: rgba(0, 0, 0, 0.4) !important;
 font-family: "Inter Tight", sans-serif !important;
 font-size: 13px !important;
 font-weight: 500 !important;
 line-height: 1.0588rem !important;
 text-align: left !important;
 letter-spacing: 0px;
}

.globo-form-app:not([data-id="96192"]) .submit {
 background: #000 !important;
 border: none !important;
 border-radius: 30px !important;
 color: #fff !important;
 cursor: pointer !important;
 font-family: Inter Tight, sans-serif !important;
 font-size: 16px !important;
 font-weight: 600 !important;
 line-height: 19.3px !important;
 padding: 12px 0 13px !important;
 text-align: center !important;
 -webkit-transition: .3s;
 transition: .3s;
 width: 100% !important;
 margin-top: 40px!important;
 border: 1px solid #000 !important;
}

.globo-form-app:not([data-id="96192"]) button.previous {
 border: none !important;
 border-radius: 30px !important;
 cursor: pointer !important;
 font-family: Inter Tight, sans-serif !important;
 font-size: 16px !important;
 font-weight: 600 !important;
 line-height: 19.3px !important;
 padding: 12px 0 13px !important;
 text-align: center !important;
 -webkit-transition: .3s;
 transition: .3s;
 margin-top: 40px!important;
 border: 1px solid #000 !important;
}

